    @EventHandler
    public void on( DeleteOpportunityStageHistoryEvent event) {
    	OpportunityStageHistory entity = new OpportunityStageHistory();
   
    	// ------------------------------------------
    	// apply the OpportunityStageHistoryId
    	// ------------------------------------------
    	entity.setOpportunityStageHistoryId( event.getOpportunityStageHistoryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
